#!/usr/bin/env bash
# WARNING: This script has been AI generated by CLAUDE OPUS
# One command to go from nothing to a working pretrained GPT-2.
#
# Downloads a checkpoint and its tokenizer, checks it really is the model you
# asked for, dumps reference activations from PyTorch, verifies our forward
# pass against them, and then tells you how to run it.
#
#   ./scripts/setup_gpt2.sh                # gpt2 small, the sensible first one
#   ./scripts/setup_gpt2.sh gpt2-medium
#   ./scripts/setup_gpt2.sh gpt2-xl --int8
#
# Options:
#   --force         delete models/<name> first and start over
#   --skip-verify   skip the PyTorch comparison (not recommended)
#   --int8          print the int8 run commands at the end
#
# Safe to re-run. Anything already downloaded is left alone, so an interrupted
# download resumes rather than restarting, and a finished setup just
# re-verifies and reprints the commands.
#
# Runs on Linux, macOS and Windows (Git Bash / MSYS2 / WSL). Targets bash 3.2,
# which is what macOS still ships, and avoids GNU-only flags.

set -uo pipefail

cd "$(dirname "${BASH_SOURCE[0]}")/.." || exit 1
REPO_ROOT="$(pwd)"

# ---------------------------------------------------------------------------
# arguments
# ---------------------------------------------------------------------------

MODEL="gpt2"
FORCE=0
SKIP_VERIFY=0
USE_INT8=0

first=1
for arg in "$@"; do
  case "$arg" in
    --force)       FORCE=1 ;;
    --skip-verify) SKIP_VERIFY=1 ;;
    --int8)        USE_INT8=1 ;;
    -h|--help)
      sed -n '3,24p' "${BASH_SOURCE[0]}" | sed 's/^#[[:space:]]\{0,1\}//'
      exit 0
      ;;
    -*)
      printf 'unknown option: %s  (try --help)\n' "$arg" >&2
      exit 1
      ;;
    *)
      if [ "$first" = "1" ]; then
        MODEL="$arg"
        first=0
      else
        printf 'unexpected argument: %s  (try --help)\n' "$arg" >&2
        exit 1
      fi
      ;;
  esac
done

DIR="models/$MODEL"
HF_BASE="https://huggingface.co/openai-community/$MODEL/resolve/main"

# ---------------------------------------------------------------------------
# output helpers. plain text, no colour -> this gets piped and logged
# ---------------------------------------------------------------------------

step() { printf '\n==> %s\n' "$*"; }
info() { printf '    %s\n' "$*"; }
warn() { printf '    WARNING: %s\n' "$*" >&2; }

die() {
  printf '\nFAILED: %s\n' "$*" >&2

  # do not leave an empty model directory lying around after a failed first
  # download -> next time round it would look like a half finished setup.
  # rmdir only succeeds on an empty directory, which is exactly the guard we
  # want: anything already downloaded is kept so a retry can resume it
  if [ -n "${DIR:-}" ] && [ -d "$DIR" ]; then
    rmdir "$DIR" 2>/dev/null && printf '        (removed the empty %s)\n' "$DIR" >&2
  fi

  exit 1
}

# ---------------------------------------------------------------------------
# platform
# ---------------------------------------------------------------------------

case "$(uname -s 2>/dev/null || echo unknown)" in
  Linux*)                      PLATFORM="linux" ;;
  Darwin*)                     PLATFORM="macos" ;;
  MINGW*|MSYS*|CYGWIN*)        PLATFORM="windows" ;;
  *)                           PLATFORM="unknown" ;;
esac

# WSL reports Linux, which is correct -> everything there lives on PATH

# windows needs the .exe, everywhere else has no suffix
EXE_SUFFIX=""
[ "$PLATFORM" = "windows" ] && EXE_SUFFIX=".exe"

# ---------------------------------------------------------------------------
# finding our tools
#
# on Linux and macOS this is just PATH and we are done. the fallback list
# exists for Windows under Git Bash, where the bash PATH is nearly empty even
# though go, python and make all work fine from PowerShell -> go lives under
# "Program Files" and python under AppData, neither of which bash knows about
# ---------------------------------------------------------------------------

# On Windows, make sure USERPROFILE and LOCALAPPDATA exist and are EXPORTED.
#
# this matters more than it looks. the Go toolchain is a native Windows binary
# and finds its module cache and build cache through those two variables, so
# without them it refuses to do anything:
#
#   go: module cache not found: neither GOMODCACHE nor GOPATH is set
#   build cache is required, but could not be located: GOCACHE is not defined
#
# run from Git Bash they are both present. run from inside an MSYS2 make
# recipe they are stripped, HOME becomes /home/<user> which does not exist on
# disk, and asking cmd.exe does not help either because it inherits the same
# stripped environment. the MSYS2 registry mount does know, so try that, and
# fall back to assembling the path from the home root and the user name
resolve_windows_env() {
  [ "$PLATFORM" = "windows" ] || return 0

  registry_env() {
    reg_path="/proc/registry/HKEY_CURRENT_USER/Volatile Environment/$1"
    [ -r "$reg_path" ] || return 1
    # these values are NUL terminated
    tr -d '\0\r\n' < "$reg_path"
  }

  if [ -z "${USERPROFILE:-}" ]; then
    USERPROFILE="$(registry_env USERPROFILE 2>/dev/null)" || USERPROFILE=""

    if [ -z "$USERPROFILE" ] && command -v cygpath >/dev/null 2>&1; then
      # cygpath -H gives the home ROOT, e.g. /c/Users, so add the user name
      home_root="$(cygpath -H 2>/dev/null)"
      user_name="$(id -un 2>/dev/null)"
      if [ -n "$home_root" ] && [ -n "$user_name" ] && [ -d "$home_root/$user_name" ]; then
        USERPROFILE="$(cygpath -w "$home_root/$user_name" 2>/dev/null)"
      fi
    fi
  fi

  if [ -n "${USERPROFILE:-}" ]; then
    export USERPROFILE

    if [ -z "${LOCALAPPDATA:-}" ]; then
      LOCALAPPDATA="$(registry_env LOCALAPPDATA 2>/dev/null)" || LOCALAPPDATA=""
      [ -z "$LOCALAPPDATA" ] && LOCALAPPDATA="${USERPROFILE}\\AppData\\Local"
    fi
    export LOCALAPPDATA
  fi
}

resolve_windows_env

# win_env returns one of those, now that they have been resolved
win_env() {
  case "$1" in
    USERPROFILE)  printf '%s\n' "${USERPROFILE:-}" ;;
    LOCALAPPDATA) printf '%s\n' "${LOCALAPPDATA:-}" ;;
    *)            printf '\n' ;;
  esac
}

# to_posix turns a Windows path into one this shell understands. only used on
# Windows, and deliberately avoids GNU-only sed features so it does not
# explode on macOS if it is ever reached
to_posix() {
  raw="${1:-}"
  [ -n "$raw" ] || return 0

  if command -v cygpath >/dev/null 2>&1; then
    cygpath -u "$raw" 2>/dev/null && return 0
  fi

  # C:\Users\x -> /c/Users/x. tr for the lowercasing, since sed's \L is GNU only
  drive=$(printf '%s' "$raw" | cut -c1 | tr '[:upper:]' '[:lower:]')
  rest=$(printf '%s' "$raw" | cut -c3- | tr '\\' '/')
  printf '/%s%s\n' "$drive" "$rest"
}

# find_tool NAME [fallback paths or globs...] -> prints the path, or fails
#
# the candidates arrive as separate arguments, because "Program Files" has a
# space in it and a space separated string would split straight down the
# middle of it. and the inner loop clears IFS so that an unquoted expansion
# still GLOBS (python lives in a versioned directory) without also splitting
# on spaces -> that combination is the only way to get both
find_tool() {
  name="$1"; shift

  if command -v "$name" >/dev/null 2>&1; then
    command -v "$name"
    return 0
  fi

  saved_ifs="$IFS"
  IFS=''
  for candidate in "$@"; do
    for expanded in $candidate; do
      if [ -x "$expanded" ]; then
        IFS="$saved_ifs"
        printf '%s\n' "$expanded"
        return 0
      fi
    done
  done
  IFS="$saved_ifs"

  return 1
}

# arrays, so a path containing a space stays one path. bash 3.2 has these,
# which is the oldest version we care about (macOS still ships it)
GO_FALLBACKS=()
PY_FALLBACKS=()

case "$PLATFORM" in
  linux)
    # the official tarball location, which the installer does not add to PATH
    GO_FALLBACKS=(/usr/local/go/bin/go "$HOME/go/bin/go" /snap/bin/go)
    PY_FALLBACKS=(/usr/bin/python3 /usr/local/bin/python3)
    ;;
  macos)
    # homebrew on apple silicon, then intel, then the official pkg
    GO_FALLBACKS=(/opt/homebrew/bin/go /usr/local/bin/go /usr/local/go/bin/go)
    PY_FALLBACKS=(
      /opt/homebrew/bin/python3
      /usr/local/bin/python3
      "/Library/Frameworks/Python.framework/Versions/3.*/bin/python3"
      /usr/bin/python3
    )
    ;;
  windows)
    appdata="$(to_posix "$(win_env LOCALAPPDATA)")"
    GO_FALLBACKS=("/c/Program Files/Go/bin/go.exe" /c/Go/bin/go.exe)
    # globs, because python installs into a version numbered directory
    PY_FALLBACKS=(
      "${appdata}/Programs/Python/Python3*/python.exe"
      "/c/Program Files/Python3*/python.exe"
      "/c/Python3*/python.exe"
    )
    ;;
esac

# "${arr[@]+...}" so an empty array does not trip set -u on bash 3.2
GO="$(find_tool go ${GO_FALLBACKS[@]+"${GO_FALLBACKS[@]}"})" || GO=""
[ -n "$GO" ] || die "could not find the go toolchain.
       Install it from https://go.dev/dl/ or put it on PATH."

# finding the binary is not the same as being able to run it. go locates its
# module cache under GOPATH, which it derives from the user's home directory,
# and in a stripped environment it cannot work that out:
#
#   go: module cache not found: neither GOMODCACHE nor GOPATH is set
#
# that is not a problem with this repo or the download, so figure out a GOPATH
# ourselves rather than letting it surface later as a confusing failure
ensure_go_env() {
  "$GO" env GOMODCACHE >/dev/null 2>&1 && return 0

  profile="$(win_env USERPROFILE)"
  if [ -n "$profile" ]; then
    # a native Windows go.exe wants a native path here, backslashes and all,
    # NOT the /c/... form this shell uses
    GOPATH="${profile}\\go"
    export GOPATH
    "$GO" env GOMODCACHE >/dev/null 2>&1 && return 0
  fi

  if [ -n "${HOME:-}" ] && [ -d "$HOME" ]; then
    GOPATH="$HOME/go"
    export GOPATH
    "$GO" env GOMODCACHE >/dev/null 2>&1 && return 0
  fi

  return 1
}

ensure_go_env || die "found go at $GO but it cannot locate its module cache.
       Set GOPATH or GOMODCACHE and re-run, for example:
         export GOPATH=\"\$HOME/go\""

# python needs a different rule from go. there is often more than one
# installed, and the one we want is not the newest or the first on PATH -> it
# is whichever has torch in it. so gather every candidate and prefer one that
# can actually import what the dumper needs, falling back to any python at all
# so we can still print a useful pip hint
PYTHON=""
PYTHON_READY=0

collect_pythons() {
  for name in python3 python; do
    if command -v "$name" >/dev/null 2>&1; then
      command -v "$name"
    fi
  done

  saved_ifs="$IFS"
  IFS=''
  for candidate in ${PY_FALLBACKS[@]+"${PY_FALLBACKS[@]}"}; do
    for expanded in $candidate; do
      [ -x "$expanded" ] && printf '%s\n' "$expanded"
    done
  done
  IFS="$saved_ifs"
}

while IFS= read -r candidate; do
  [ -n "$candidate" ] || continue

  if "$candidate" -c "import torch, transformers, safetensors" >/dev/null 2>&1; then
    PYTHON="$candidate"
    PYTHON_READY=1
    break
  fi

  # remember the first working interpreter even without the libraries, so the
  # "you need to pip install" message can still be specific
  [ -z "$PYTHON" ] && "$candidate" -c "pass" >/dev/null 2>&1 && PYTHON="$candidate"
done <<EOF
$(collect_pythons)
EOF

# a downloader. curl is everywhere except some minimal Linux images, where
# wget usually is instead
DOWNLOADER=""
if command -v curl >/dev/null 2>&1; then
  DOWNLOADER="curl"
elif command -v wget >/dev/null 2>&1; then
  DOWNLOADER="wget"
else
  die "neither curl nor wget is available, and one of them is how the weights get downloaded"
fi

# ---------------------------------------------------------------------------
# 0. sanity
# ---------------------------------------------------------------------------

step "Setting up $MODEL"
info "platform  : $PLATFORM"
info "repo      : $REPO_ROOT"
info "target    : $DIR"
info "go        : $GO"
info "downloader: $DOWNLOADER"
if [ "$PYTHON_READY" = "1" ]; then
  info "python    : $PYTHON (torch available)"
elif [ -n "$PYTHON" ]; then
  info "python    : $PYTHON (no torch -> verification will be skipped)"
else
  info "python    : not found (verification will be skipped)"
fi

case "$MODEL" in
  gpt2|gpt2-medium|gpt2-large|gpt2-xl) ;;
  *)
    warn "$MODEL is not one of the four published GPT-2 sizes."
    warn "The loader infers the head count from the hidden dimension, so an"
    warn "unknown size may need --heads passed by hand when you run it."
    ;;
esac

if [ "$FORCE" = "1" ] && [ -d "$DIR" ]; then
  step "Removing $DIR because --force was given"
  rm -rf "$DIR" || die "could not remove $DIR"
fi

mkdir -p "$DIR" || die "could not create $DIR"

# ---------------------------------------------------------------------------
# 1. the downloads
#
# four files. the big one is the weights, the other three come to about 1.5MB
# between them. vocab.json and merges.txt are IDENTICAL across all four sizes,
# so if another size is already set up locally we copy instead of downloading
# ---------------------------------------------------------------------------

download() {
  url="$1"
  target="$2"

  if [ "$DOWNLOADER" = "curl" ]; then
    # -f so an HTTP error is a failure rather than a saved error page,
    # -L to follow redirects, -C - to resume a partial file
    curl -fL -C - --retry 3 --retry-delay 2 -o "$target" "$url" && return 0
    # a zero length or already complete file can make a resume fail, so try
    # once more from scratch
    rm -f "$target"
    curl -fL --retry 3 --retry-delay 2 -o "$target" "$url"
  else
    wget -c -O "$target" "$url" && return 0
    rm -f "$target"
    wget -O "$target" "$url"
  fi
}

human_size() {
  # du -h is in POSIX and prints a human size on every platform we target.
  # purely cosmetic, so a failure here must not fail the script
  du -h "$1" 2>/dev/null | cut -f1 || printf '?'
}

fetch() {
  name="$1"
  target="$DIR/$name"

  if [ -s "$target" ]; then
    info "$name already present ($(human_size "$target")), skipping"
    return 0
  fi

  # the tokenizer files are shared between every gpt-2 size
  if [ "$name" = "vocab.json" ] || [ "$name" = "merges.txt" ]; then
    for other in models/gpt2 models/gpt2-medium models/gpt2-large models/gpt2-xl; do
      if [ "models/$MODEL" != "$other" ] && [ -s "$other/$name" ]; then
        info "$name copied from $other (identical for every GPT-2 size)"
        cp "$other/$name" "$target" && return 0
      fi
    done
  fi

  info "downloading $name ..."
  download "$HF_BASE/$name" "$target" \
    || die "could not download $name from $HF_BASE"

  [ -s "$target" ] || die "$name downloaded as an empty file"
}

step "Fetching files into $DIR"
fetch config.json
fetch vocab.json
fetch merges.txt
fetch model.safetensors

# ---------------------------------------------------------------------------
# 2. is this actually the model we asked for
#
# inspect-safetensors parses the header, so it doubles as a check that the
# download is a real safetensors file rather than a truncated one
# ---------------------------------------------------------------------------

# build the binary once instead of `go run` per command. three go run calls
# recompile the same thing three times, and it also separates "the toolchain
# is broken" from "the checkpoint is broken" -> a compile failure here used to
# surface as a misleading "your download is truncated"
step "Building"
BINARY="./gpt-go-setup$EXE_SUFFIX"
"$GO" build -tags blas -o "$BINARY" . \
  || die "the project did not compile. That is not a problem with the download."
trap 'rm -f "$BINARY"' EXIT

step "Checking the checkpoint"
"$BINARY" inspect-safetensors --file "$DIR/model.safetensors" \
  || die "could not read $DIR/model.safetensors
       Delete it and re-run -> the download is most likely truncated."

step "Loading it through the Go model"
"$BINARY" load-gpt2 --weights "$DIR/model.safetensors" \
  || die "the loader rejected the checkpoint"

# ---------------------------------------------------------------------------
# 3. prove it is correct
#
# this is the step people want to skip and should not. a mis-loaded model does
# not error, it produces fluent nonsense that reads like a badly trained one
# ---------------------------------------------------------------------------

VERIFIED=0
PIP_HINT_1="pip install torch --index-url https://download.pytorch.org/whl/cpu"
PIP_HINT_2="pip install transformers safetensors"

if [ "$SKIP_VERIFY" = "1" ]; then
  warn "skipping verification because --skip-verify was given"
elif [ -z "$PYTHON" ]; then
  warn "no python found, so the reference activations cannot be generated."
  warn "Install python 3 and re-run, then:"
  warn "  $PIP_HINT_1"
  warn "  $PIP_HINT_2"
elif [ "$PYTHON_READY" != "1" ]; then
  warn "found python at $PYTHON but it is missing torch/transformers/safetensors:"
  warn "  $PYTHON -m $PIP_HINT_1"
  warn "  $PYTHON -m $PIP_HINT_2"
else
  REF="$DIR/reference_activations.safetensors"

  if [ -s "$REF" ]; then
    info "reference dump already present, reusing it"
  else
    step "Dumping reference activations from PyTorch"
    # --model points at our local directory so the weights are read from disk
    # rather than downloaded a second time, and --tokens skips the tokenizer
    # so only config.json is needed here
    "$PYTHON" scripts/dump_gpt2_reference.py \
      --model "$DIR" \
      --tokens 464,1989,286,30185,318 \
      --prompt "The area of Antarctica is" \
      --out-dir "$DIR" \
      || die "the reference dump failed"
  fi

  step "Verifying our forward pass against PyTorch"
  if "$GO" run -tags blas main.go verify-gpt2 \
      --weights "$DIR/model.safetensors" --reference "$REF"; then
    VERIFIED=1
  else
    die "verification failed -> do not trust the output until this passes.
       The table above names the first tensor that diverged."
  fi
fi

# ---------------------------------------------------------------------------
# 4. tell them what to run
# ---------------------------------------------------------------------------

INT8_FLAG=""
if [ "$USE_INT8" = "1" ]; then
  INT8_FLAG=" --int8"
fi

step "Done"
if [ "$VERIFIED" = "1" ]; then
  info "$MODEL is set up and verified correct against PyTorch."
else
  info "$MODEL is set up, but NOT verified. See the warnings above."
fi
info ""
info "Interactive, loads the weights once:"
info "  go run -tags blas main.go gpt2-repl --dir $DIR$INT8_FLAG"
info ""
info "One-shot:"
info "  go run -tags blas main.go gpt2-run --dir $DIR$INT8_FLAG \\"
info "      --prompt \"The area of Antarctica is\" --tokens 60 --temperature 0.7"
info ""
info "Or build once and skip the compile each time:"
info "  go build -tags blas -o gpt-go ."
info "  ./gpt-go gpt2-repl --dir $DIR$INT8_FLAG"
if [ "$USE_INT8" = "1" ]; then
  info ""
  info "int8: roughly 40% less memory, about 3x slower, ~1% logit error."
fi
if [ "$PLATFORM" = "windows" ] && ! command -v go >/dev/null 2>&1; then
  info ""
  info "Note: go is not on this shell's PATH, so those commands need the full"
  info "path, or run them from PowerShell where it is:"
  info "  \"$GO\" run -tags blas main.go gpt2-repl --dir $DIR$INT8_FLAG"
fi
info ""

exit 0
